35	  /// A GitHub reviewer. A user → `github.com/<login>.png`; a team → no image (initials on the slug).
36	  init(reviewer identity: Reviewer.Identity, displayName: String, pixelSize: Int) {
37	    self.displayName = displayName
38	    switch identity {
39	    case .user(let login):
40	      seed = login.lowercased()
41	      imageURL = Self.githubAvatar(login: login, pixelSize: pixelSize)
42	    case .team(let slug):
43	      seed = "team:" + slug.lowercased()
44	      imageURL = nil
