48	  /// `https://www.gravatar.com/avatar/<md5(lowercased-trimmed-email)>?s=<px>&d=404`. `d=404` makes
49	  /// Gravatar 404 (not serve an identicon) when it has no image for the address, so the load fails
50	  /// and the initials chip shows — the same fallback path as an unknown GitHub login.
51	  private static func gravatar(email: String, pixelSize: Int) -> URL? {
52	    let normalized = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
53	    guard !normalized.isEmpty else { return nil }
54	    let hash = Insecure.MD5.hash(data: Data(normalized.utf8))
55	      .map { String(format: "%02x", $0) }.joined()
56	    return URL(string: "https://www.gravatar.com/avatar/\(hash)?s=\(pixelSize)&d=404")
57	  }
