67	  /// Initials for the fallback chip: first letters of the first two words, or the first two letters
68	  /// of a single-word name (e.g. "octocat" → "OC"). "?" when there's nothing to show.
69	  var initials: String {
70	    let words = displayName.split(whereSeparator: { $0 == " " || $0 == "\t" })
71	    guard let first = words.first, let firstChar = first.first else { return "?" }
72	    if words.count >= 2, let secondChar = words[1].first {
73	      return String([firstChar, secondChar]).uppercased()
