78	  /// Deterministic fill colour for the initials chip. Uses a stable FNV-1a hash of the seed (NOT
79	  /// `String.hashValue`, which is per-process salted and would recolour every launch) mapped onto
80	  /// the hue wheel at a fixed saturation/brightness that reads on both light and dark themes.
81	  func fillColor() -> NSColor {
82	    var hash: UInt64 = 1_469_598_103_934_665_603  // FNV-1a offset basis
83	    for byte in seed.utf8 {
84	      hash ^= UInt64(byte)
85	      hash = hash &* 1_099_511_628_211
86	    }
87	    let hue = Double(hash % 360) / 360.0
88	    return NSColor(hue: hue, saturation: 0.55, brightness: 0.72, alpha: 1)
89	  }
